import * as React from "react";

type PossibleRef<T> = React.Ref<T> | undefined;

function assignRef<T>(ref: PossibleRef<T>, value: T | null): void {
  if (typeof ref === "function") ref(value);
  else if (ref != null) (ref as React.MutableRefObject<T | null>).current = value;
}

/**
 * Merge several refs into one callback ref. Use when a component keeps an
 * internal ref to its root element but must also honour a forwarded `ref` (so
 * consumers can measure/focus it) -- the DS composites that forward refs use
 * this. Prefer `useMergedRefs` inside components so the callback stays stable
 * across renders.
 */
export function mergeRefs<T>(...refs: PossibleRef<T>[]): React.RefCallback<T> {
  return (node: T | null) => {
    for (const ref of refs) assignRef(ref, node);
  };
}

/**
 * Hook form of `mergeRefs`: returns a stable merged callback ref. The refs are
 * used as the memo dependencies, so it re-creates only if a ref identity
 * changes (internal `useRef` objects and forwarded refs are stable, so in
 * practice it never does).
 */
export function useMergedRefs<T>(...refs: PossibleRef<T>[]): React.RefCallback<T> {
  // eslint-disable-next-line react-hooks/exhaustive-deps
  return React.useCallback(mergeRefs(...refs), refs);
}
